create function pg_temp.doc_assert(ok boolean)returns void language plpgsql as $$begin if ok is not true then raise exception 'document assertion';end if;end$$;
create function pg_temp.doc_deny(q text,c text)returns void language plpgsql as $$declare actual text;begin begin execute q;exception when others then actual:=sqlstate;end;if actual is distinct from c then raise exception 'document expected %, got %',c,actual;end if;end$$;
set local role authenticated;select set_config('request.jwt.claim.sub','a9000000-0000-4000-8000-000000000001',true);
do $$declare w uuid:='b9000000-0000-4000-8000-000000000001';id uuid:='d9000000-0000-4000-8000-000000000001';p jsonb;v jsonb;r jsonb;begin
 p:=public.document_v1_list(w,'{"target_kind":"customer","target_id":"c9000000-0000-4000-8000-000000000001","limit":1}');perform pg_temp.doc_assert(jsonb_array_length(p->'items')=1 and p->>'next_id'=id::text and not p::text~'(Sensitive|storage_path|sha256|file_name)');
 p:=public.document_v1_list(w,'{"target_kind":"customer","target_id":"c9000000-0000-4000-8000-000000000001","limit":1,"after_id":"d9000000-0000-4000-8000-000000000001"}');perform pg_temp.doc_assert(p->'items'->0->>'id'='d9000000-0000-4000-8000-000000000002');
